pub type AxResult<T> = Result<T, AxError>;

pub type AxUsageContext = Value;
pub type AxUsageEvent = Value;
pub type AxUsageObserver = Arc<dyn Fn(AxUsageEvent) + Send + Sync>;

#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
pub struct AxRateLimitInfo {
    pub operation: String,
    pub provider: String,
    pub model: String,
    pub streaming: bool,
    pub previous_model_usage: Option<Value>,
}

pub trait AxRateLimiter: Send + Sync {
    fn run(
        &self,
        next: &mut dyn FnMut() -> AxResult<Value>,
        info: &AxRateLimitInfo,
    ) -> AxResult<Value>;
}

impl<F> AxRateLimiter for F
where
    F: Fn(&mut dyn FnMut() -> AxResult<Value>, &AxRateLimitInfo) -> AxResult<Value> + Send + Sync,
{
    fn run(
        &self,
        next: &mut dyn FnMut() -> AxResult<Value>,
        info: &AxRateLimitInfo,
    ) -> AxResult<Value> {
        self(next, info)
    }
}

#[derive(Clone, Debug, Default)]
pub struct AxSpanStart {
    pub name: String,
    pub kind: String,
    pub attributes: BTreeMap<String, Value>,
    pub parent: Option<Arc<dyn AxSpan>>,
}

pub trait AxSpan: Send + Sync + fmt::Debug {
    fn set_attributes(&self, _attributes: &BTreeMap<String, Value>) {}
    fn add_event(&self, _name: &str, _attributes: &BTreeMap<String, Value>) {}
    fn record_exception(&self, _error: &AxError) {}
    fn set_status(&self, _status: &str, _description: Option<&str>) {}
    fn end(&self) {}
}

pub trait AxTracer: Send + Sync {
    fn start_span(&self, start: AxSpanStart) -> Option<Arc<dyn AxSpan>>;
}

#[derive(Clone, Debug, Default)]
pub struct AxMetricInstrumentOptions {
    pub description: Option<String>,
    pub unit: Option<String>,
}

pub trait AxCounter: Send + Sync {
    fn add(&self, value: f64, attributes: &BTreeMap<String, Value>);
}

pub trait AxHistogram: Send + Sync {
    fn record(&self, value: f64, attributes: &BTreeMap<String, Value>);
}

pub trait AxGauge: Send + Sync {
    fn record(&self, value: f64, attributes: &BTreeMap<String, Value>);
}

pub trait AxMeter: Send + Sync {
    fn create_counter(
        &self,
        name: &str,
        options: &AxMetricInstrumentOptions,
    ) -> Option<Arc<dyn AxCounter>>;
    fn create_histogram(
        &self,
        name: &str,
        options: &AxMetricInstrumentOptions,
    ) -> Option<Arc<dyn AxHistogram>>;
    fn create_gauge(
        &self,
        name: &str,
        options: &AxMetricInstrumentOptions,
    ) -> Option<Arc<dyn AxGauge>>;
}

#[derive(Clone, Default)]
pub struct AxRuntimeHooks {
    pub rate_limiter: Option<Arc<dyn AxRateLimiter>>,
    pub tracer: Option<Arc<dyn AxTracer>>,
    pub meter: Option<Arc<dyn AxMeter>>,
}

static RUNTIME_HOOK_GLOBALS: OnceLock<Mutex<AxRuntimeHooks>> = OnceLock::new();

pub fn set_rate_limiter(rate_limiter: Option<Arc<dyn AxRateLimiter>>) {
    if let Ok(mut hooks) = RUNTIME_HOOK_GLOBALS
        .get_or_init(|| Mutex::new(AxRuntimeHooks::default()))
        .lock()
    {
        hooks.rate_limiter = rate_limiter;
    }
}

pub fn set_tracer(tracer: Option<Arc<dyn AxTracer>>) {
    if let Ok(mut hooks) = RUNTIME_HOOK_GLOBALS
        .get_or_init(|| Mutex::new(AxRuntimeHooks::default()))
        .lock()
    {
        hooks.tracer = tracer;
    }
}

pub fn set_meter(meter: Option<Arc<dyn AxMeter>>) {
    if let Ok(mut hooks) = RUNTIME_HOOK_GLOBALS
        .get_or_init(|| Mutex::new(AxRuntimeHooks::default()))
        .lock()
    {
        hooks.meter = meter;
    }
}

#[derive(Clone, Default)]
struct RuntimeHookFrame {
    hooks: AxRuntimeHooks,
    span: Option<Arc<dyn AxSpan>>,
}

thread_local! {
    static RUNTIME_HOOK_FRAMES: RefCell<Vec<RuntimeHookFrame>> = const { RefCell::new(Vec::new()) };
}

fn snapshot_runtime_globals() -> AxRuntimeHooks {
    RUNTIME_HOOK_GLOBALS
        .get_or_init(|| Mutex::new(AxRuntimeHooks::default()))
        .lock()
        .map(|hooks| hooks.clone())
        .unwrap_or_default()
}

fn merge_runtime_hooks(
    explicit: Option<&AxRuntimeHooks>,
    enclosing: Option<&AxRuntimeHooks>,
    defaults: Option<&AxRuntimeHooks>,
) -> AxRuntimeHooks {
    let inherited = RUNTIME_HOOK_FRAMES.with(|frames| frames.borrow().last().cloned());
    let globals = if inherited.is_none() {
        snapshot_runtime_globals()
    } else {
        AxRuntimeHooks::default()
    };
    let sources = [
        explicit,
        enclosing,
        inherited.as_ref().map(|frame| &frame.hooks),
        defaults,
        Some(&globals),
    ];
    AxRuntimeHooks {
        rate_limiter: sources
            .iter()
            .find_map(|source| source.and_then(|h| h.rate_limiter.clone())),
        tracer: sources
            .iter()
            .find_map(|source| source.and_then(|h| h.tracer.clone())),
        meter: sources
            .iter()
            .find_map(|source| source.and_then(|h| h.meter.clone())),
    }
}

fn current_runtime_hooks() -> Option<AxRuntimeHooks> {
    RUNTIME_HOOK_FRAMES.with(|frames| frames.borrow().last().map(|frame| frame.hooks.clone()))
}

fn current_runtime_parent_span() -> Option<Arc<dyn AxSpan>> {
    RUNTIME_HOOK_FRAMES.with(|frames| frames.borrow().last().and_then(|frame| frame.span.clone()))
}

fn start_runtime_span(
    hooks: &AxRuntimeHooks,
    name: &str,
    kind: &str,
    attributes: &BTreeMap<String, Value>,
) -> Option<Arc<dyn AxSpan>> {
    hooks.tracer.as_ref().and_then(|tracer| {
        std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            tracer.start_span(AxSpanStart {
                name: name.to_string(),
                kind: kind.to_string(),
                attributes: attributes.clone(),
                parent: current_runtime_parent_span(),
            })
        }))
        .ok()
        .flatten()
    })
}

fn finish_runtime_span(span: &Option<Arc<dyn AxSpan>>, error: Option<&AxError>) {
    if let Some(span) = span {
        let _ = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            if let Some(error) = error {
                span.record_exception(error);
                span.set_status("error", Some(&error.message));
            } else {
                span.set_status("ok", None);
            }
            span.end();
        }));
    }
}

struct RuntimeHookScope {
    finished: bool,
}

impl RuntimeHookScope {
    fn enter(hooks: AxRuntimeHooks, span: Option<Arc<dyn AxSpan>>) -> Self {
        RUNTIME_HOOK_FRAMES
            .with(|frames| frames.borrow_mut().push(RuntimeHookFrame { hooks, span }));
        Self { finished: false }
    }

    fn finish<T>(&mut self, result: &AxResult<T>) {
        if self.finished {
            return;
        }
        let frame = RUNTIME_HOOK_FRAMES.with(|frames| frames.borrow_mut().pop());
        if let Some(frame) = frame {
            finish_runtime_span(&frame.span, result.as_ref().err());
        }
        self.finished = true;
    }
}

impl Drop for RuntimeHookScope {
    fn drop(&mut self) {
        if self.finished {
            return;
        }
        let frame = RUNTIME_HOOK_FRAMES.with(|frames| frames.borrow_mut().pop());
        if let Some(frame) = frame {
            if std::thread::panicking() {
                let error = AxError::runtime("runtime hook scope panicked");
                finish_runtime_span(&frame.span, Some(&error));
            } else {
                finish_runtime_span(&frame.span, None);
            }
        }
        self.finished = true;
    }
}

fn with_runtime_scope<T>(
    explicit: Option<&AxRuntimeHooks>,
    defaults: Option<&AxRuntimeHooks>,
    name: &str,
    kind: &str,
    attributes: BTreeMap<String, Value>,
    operation: impl FnOnce() -> AxResult<T>,
) -> AxResult<T> {
    let hooks = merge_runtime_hooks(explicit, None, defaults);
    let span = start_runtime_span(&hooks, name, kind, &attributes);
    let started = Instant::now();
    record_runtime_metrics(&hooks, kind, &attributes, None, None);
    let mut scope = RuntimeHookScope::enter(hooks, span);
    let result = operation();
    let active_hooks = current_runtime_hooks().unwrap_or_default();
    record_runtime_metrics(
        &active_hooks,
        kind,
        &attributes,
        Some(started.elapsed().as_secs_f64() * 1000.0),
        result.as_ref().err(),
    );
    scope.finish(&result);
    result
}

fn with_runtime_binding<T>(
    explicit: Option<&AxRuntimeHooks>,
    defaults: Option<&AxRuntimeHooks>,
    operation: impl FnOnce() -> AxResult<T>,
) -> AxResult<T> {
    let hooks = merge_runtime_hooks(explicit, None, defaults);
    let mut scope = RuntimeHookScope::enter(hooks, None);
    let result = operation();
    scope.finish(&result);
    result
}

#[derive(Clone, Default)]
struct RuntimeMeterInstruments {
    requests: Option<Arc<dyn AxCounter>>,
    errors: Option<Arc<dyn AxCounter>>,
    duration: Option<Arc<dyn AxHistogram>>,
    active: Option<Arc<dyn AxGauge>>,
}

struct RuntimeMeterCacheEntry {
    meter: Weak<dyn AxMeter>,
    instruments: RuntimeMeterInstruments,
}

static RUNTIME_METER_CACHE: OnceLock<Mutex<BTreeMap<(usize, String), RuntimeMeterCacheEntry>>> =
    OnceLock::new();

fn runtime_meter_instruments(meter: &Arc<dyn AxMeter>, namespace: &str) -> RuntimeMeterInstruments {
    let identity = Arc::as_ptr(meter) as *const () as usize;
    let key = (identity, namespace.to_string());
    if let Ok(mut cache) = RUNTIME_METER_CACHE
        .get_or_init(|| Mutex::new(BTreeMap::new()))
        .lock()
    {
        let cached = cache.get(&key).and_then(|entry| {
            entry.meter.upgrade().and_then(|cached_meter| {
                Arc::ptr_eq(&cached_meter, meter).then(|| entry.instruments.clone())
            })
        });
        if let Some(cached) = cached {
            return cached;
        }
        cache.remove(&key);
    }
    let created = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        let count_options = AxMetricInstrumentOptions {
            description: Some("Ax runtime operations".to_string()),
            unit: Some("{operation}".to_string()),
        };
        let duration_options = AxMetricInstrumentOptions {
            description: Some("Ax runtime operation duration".to_string()),
            unit: Some("ms".to_string()),
        };
        RuntimeMeterInstruments {
            requests: meter.create_counter(&format!("{namespace}_requests"), &count_options),
            errors: meter.create_counter(&format!("{namespace}_errors"), &count_options),
            duration: meter
                .create_histogram(&format!("{namespace}_duration_ms"), &duration_options),
            active: meter.create_gauge(
                &format!("{namespace}_active_requests"),
                &AxMetricInstrumentOptions::default(),
            ),
        }
    }))
    .unwrap_or_default();
    if let Ok(mut cache) = RUNTIME_METER_CACHE
        .get_or_init(|| Mutex::new(BTreeMap::new()))
        .lock()
    {
        cache.insert(
            key,
            RuntimeMeterCacheEntry {
                meter: Arc::downgrade(meter),
                instruments: created.clone(),
            },
        );
    }
    created
}

fn record_runtime_metrics(
    hooks: &AxRuntimeHooks,
    kind: &str,
    attributes: &BTreeMap<String, Value>,
    duration_ms: Option<f64>,
    error: Option<&AxError>,
) {
    let Some(meter) = &hooks.meter else { return };
    let namespace = if kind == "client" { "ax_llm" } else { "ax_gen" };
    let instruments = runtime_meter_instruments(meter, namespace);
    let _ = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        if let Some(duration_ms) = duration_ms {
            if let Some(duration) = &instruments.duration {
                duration.record(duration_ms, attributes);
            }
            if let Some(active) = &instruments.active {
                active.record(0.0, attributes);
            }
            if error.is_some() {
                if let Some(errors) = &instruments.errors {
                    errors.add(1.0, attributes);
                }
            }
        } else {
            if let Some(requests) = &instruments.requests {
                requests.add(1.0, attributes);
            }
            if let Some(active) = &instruments.active {
                active.record(1.0, attributes);
            }
        }
    }));
}

static USAGE_OBSERVER: OnceLock<Mutex<Option<AxUsageObserver>>> = OnceLock::new();

pub fn set_usage_observer(observer: Option<AxUsageObserver>) {
    let state = USAGE_OBSERVER.get_or_init(|| Mutex::new(None));
    if let Ok(mut current) = state.lock() {
        *current = observer;
    }
}

fn emit_usage_event(operation: &str, response: &Value, options: &Value, streaming: bool) {
    let event = match build_usage_event(&[
        CoreValue::from(operation),
        core_value_from_json(response),
        core_value_from_json(options),
        CoreValue::Bool(streaming),
    ]) {
        Ok(value) => core_value_to_json(&value),
        Err(_) => return,
    };
    if event.is_null() {
        return;
    }
    let observer = USAGE_OBSERVER
        .get_or_init(|| Mutex::new(None))
        .lock()
        .ok()
        .and_then(|value| value.clone());
    if let Some(observer) = observer {
        let _ = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| observer(event.clone())));
    }
}

fn merge_ai_options(defaults: &Value, overrides: &Value) -> AxResult<Value> {
    let mut merged = defaults.as_object().cloned().unwrap_or_default();
    if let Some(values) = overrides.as_object() {
        for (key, value) in values {
            merged.insert(key.clone(), value.clone());
        }
    }
    let default_context = defaults
        .get("usage_context")
        .or_else(|| defaults.get("usageContext"))
        .cloned()
        .unwrap_or(Value::Null);
    let override_context = overrides
        .get("usage_context")
        .or_else(|| overrides.get("usageContext"))
        .cloned()
        .unwrap_or(Value::Null);
    let context = core_value_to_json(&merge_usage_context(&[
        core_value_from_json(&default_context),
        core_value_from_json(&override_context),
    ])?);
    if context
        .as_object()
        .map(|value| !value.is_empty())
        .unwrap_or(false)
    {
        merged.insert("usage_context".into(), context.clone());
        merged.insert("usageContext".into(), context);
    }
    Ok(Value::Object(merged))
}

fn response_model_usage(response: &Value) -> Option<Value> {
    response
        .get("model_usage")
        .or_else(|| response.get("modelUsage"))
        .or_else(|| response.get("usage"))
        .cloned()
        .or_else(|| {
            response
                .get("results")
                .and_then(Value::as_array)
                .and_then(|results| results.last())
                .and_then(|result| {
                    result
                        .get("model_usage")
                        .or_else(|| result.get("modelUsage"))
                        .or_else(|| result.get("usage"))
                })
                .cloned()
        })
}

fn run_ai_runtime_operation(
    hooks: AxRuntimeHooks,
    info: &AxRateLimitInfo,
    next: &mut dyn FnMut() -> AxResult<Value>,
) -> AxResult<Value> {
    let mut attributes = BTreeMap::new();
    attributes.insert("ax.operation".to_string(), json!(info.operation));
    attributes.insert("ax.provider".to_string(), json!(info.provider));
    attributes.insert("ax.model".to_string(), json!(info.model));
    attributes.insert("ax.streaming".to_string(), json!(info.streaming));
    let limiter = hooks.rate_limiter.clone();
    with_runtime_scope(
        Some(&hooks),
        None,
        &format!("ax_llm_{}", info.operation),
        "client",
        attributes,
        || match limiter {
            Some(limiter) => limiter.run(next, info),
            None => next(),
        },
    )
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct AxError {
    pub category: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub error_type: Option<String>,
    pub message: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub status: Option<u16>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub code: Option<String>,
    pub retryable: bool,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub response_body: Option<Value>,
}

impl AxError {
    pub fn new(category: impl Into<String>, message: impl Into<String>) -> Self {
        Self {
            category: category.into(),
            error_type: None,
            message: message.into(),
            status: None,
            code: None,
            retryable: false,
            response_body: None,
        }
    }

    pub fn runtime(message: impl Into<String>) -> Self {
        Self::new("runtime", message)
    }

    pub fn validation(message: impl Into<String>) -> Self {
        Self::new("validation", message)
    }
}

impl fmt::Display for AxError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.message)
    }
}

impl Error for AxError {}

impl From<serde_json::Error> for AxError {
    fn from(value: serde_json::Error) -> Self {
        Self::runtime(value.to_string())
    }
}

impl From<std::io::Error> for AxError {
    fn from(value: std::io::Error) -> Self {
        Self::runtime(value.to_string())
    }
}

impl From<reqwest::Error> for AxError {
    fn from(value: reqwest::Error) -> Self {
        let mut err = Self::new("ai_service", value.to_string());
        err.status = value.status().map(|status| status.as_u16());
        err.retryable = err.status.map(|status| status >= 500).unwrap_or(false);
        err
    }
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct FieldType {
    pub name: String,
    #[serde(default, rename = "isArray")]
    pub is_array: bool,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub options: Option<Vec<String>>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub fields: Option<Map<String, Value>>,
    #[serde(default, skip_serializing_if = "Option::is_none", rename = "minLength")]
    pub min_length: Option<f64>,
    #[serde(default, skip_serializing_if = "Option::is_none", rename = "maxLength")]
    pub max_length: Option<f64>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub minimum: Option<f64>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub maximum: Option<f64>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub pattern: Option<String>,
    #[serde(
        default,
        skip_serializing_if = "Option::is_none",
        rename = "patternDescription"
    )]
    pub pattern_description: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub format: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub language: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub description: Option<String>,
}

impl FieldType {
    pub fn new(name: impl Into<String>) -> Self {
        Self {
            name: name.into(),
            is_array: false,
            options: None,
            fields: None,
            min_length: None,
            max_length: None,
            minimum: None,
            maximum: None,
            pattern: None,
            pattern_description: None,
            format: None,
            language: None,
            description: None,
        }
    }

    pub fn string() -> Self {
        Self::new("string")
    }

    pub fn number() -> Self {
        Self::new("number")
    }

    pub fn boolean() -> Self {
        Self::new("boolean")
    }

    pub fn class(options: impl IntoIterator<Item = impl Into<String>>) -> Self {
        Self {
            name: "class".to_string(),
            is_array: false,
            options: Some(options.into_iter().map(Into::into).collect()),
            fields: None,
            min_length: None,
            max_length: None,
            minimum: None,
            maximum: None,
            pattern: None,
            pattern_description: None,
            format: None,
            language: None,
            description: None,
        }
    }

    pub fn array(mut self) -> Self {
        self.is_array = true;
        self
    }

    fn to_payload(&self) -> Value {
        self.to_payload_inner(false)
    }

    fn to_payload_with_description(&self) -> Value {
        self.to_payload_inner(true)
    }

    fn to_payload_inner(&self, include_description: bool) -> Value {
        let mut out = Map::new();
        out.insert("isArray".to_string(), Value::Bool(self.is_array));
        out.insert("name".to_string(), Value::String(self.name.clone()));
        if let Some(options) = &self.options {
            out.insert(
                "options".to_string(),
                Value::Array(options.iter().cloned().map(Value::String).collect()),
            );
        }
        if let Some(fields) = &self.fields {
            out.insert("fields".to_string(), Value::Object(fields.clone()));
        }
        if let Some(value) = self.min_length {
            out.insert("minLength".to_string(), json_number(value));
        }
        if let Some(value) = self.max_length {
            out.insert("maxLength".to_string(), json_number(value));
        }
        if let Some(value) = self.minimum {
            out.insert("minimum".to_string(), json_number(value));
        }
        if let Some(value) = self.maximum {
            out.insert("maximum".to_string(), json_number(value));
        }
        if let Some(value) = &self.pattern {
            out.insert("pattern".to_string(), Value::String(value.clone()));
        }
        if let Some(value) = &self.pattern_description {
            out.insert(
                "patternDescription".to_string(),
                Value::String(value.clone()),
            );
        }
        if let Some(value) = &self.format {
            out.insert("format".to_string(), Value::String(value.clone()));
        }
        if let Some(value) = &self.language {
            out.insert("language".to_string(), Value::String(value.clone()));
        }
        if include_description {
            if let Some(value) = &self.description {
                out.insert("description".to_string(), Value::String(value.clone()));
            }
        }
        Value::Object(out)
    }
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct Field {
    pub name: String,
    pub title: String,
    #[serde(rename = "type")]
    pub field_type: FieldType,
    #[serde(default, rename = "isOptional")]
    pub is_optional: bool,
    #[serde(default, rename = "isInternal")]
    pub is_internal: bool,
    #[serde(default, rename = "isCached")]
    pub is_cached: bool,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub description: Option<String>,
}

impl Field {
    pub fn new(name: impl Into<String>, field_type: FieldType) -> Self {
        let name = name.into();
        Self {
            title: title_case(&name),
            name,
            field_type,
            is_optional: false,
            is_internal: false,
            is_cached: false,
            description: None,
        }
    }
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct AxSignature {
    pub description: Option<String>,
    pub inputs: Vec<Field>,
    pub outputs: Vec<Field>,
}

impl AxSignature {
    pub fn parse(spec: &str) -> AxResult<Self> {
        let parsed = parse_signature(&[CoreValue::from(spec)])?;
        validate_signature(&[parsed.clone()])?;
        let payload = core_value_to_json(&parsed);
        let mut inputs = Vec::new();
        if let Some(items) = payload.get("inputs").and_then(Value::as_array) {
            for item in items {
                let name = item.get("name").and_then(Value::as_str).unwrap_or_default();
                inputs.push(field_from_payload(name, item));
            }
        }
        let mut outputs = Vec::new();
        if let Some(items) = payload.get("outputs").and_then(Value::as_array) {
            for item in items {
                let name = item.get("name").and_then(Value::as_str).unwrap_or_default();
                outputs.push(field_from_payload(name, item));
            }
        }
        Ok(AxSignature {
            description: payload
                .get("description")
                .and_then(Value::as_str)
                .map(ToString::to_string),
            inputs,
            outputs,
        })
    }

    pub fn get_output_fields(&self) -> &[Field] {
        &self.outputs
    }

    pub fn to_json_schema(&self, section: &str) -> Value {
        self.to_json_schema_with_options(section, &Value::Null)
    }

    pub fn to_json_schema_with_options(&self, section: &str, options: &Value) -> Value {
        let fields = if section == "inputs" {
            &self.inputs
        } else {
            &self.outputs
        };
        core_fields_value(fields)
            .and_then(|fields_value| {
                to_json_schema(&[
                    fields_value,
                    CoreValue::from("Schema"),
                    core_value_from_json(options),
                ])
            })
            .map(|schema| core_value_to_json(&schema))
            .unwrap_or(Value::Null)
    }
}

impl fmt::Display for AxSignature {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        let rendered = core_signature_value(self)
            .and_then(|value| signature_to_string(&[value]))
            .map(|value| value.text())
            .map_err(|_| fmt::Error)?;
        write!(formatter, "{rendered}")
    }
}

pub fn s(spec: &str) -> AxResult<AxSignature> {
    AxSignature::parse(spec)
}

pub struct SignatureBuilder {
    inputs: Vec<Field>,
    outputs: Vec<Field>,
}

pub fn f() -> SignatureBuilder {
    SignatureBuilder {
        inputs: Vec::new(),
        outputs: Vec::new(),
    }
}

impl SignatureBuilder {
    pub fn input(mut self, name: &str, field_type: FieldType) -> Self {
        self.inputs.push(Field::new(name, field_type));
        self
    }

    pub fn output(mut self, name: &str, field_type: FieldType) -> Self {
        self.outputs.push(Field::new(name, field_type));
        self
    }

    pub fn build(self) -> AxSignature {
        AxSignature {
            description: None,
            inputs: self.inputs,
            outputs: self.outputs,
        }
    }
}

fn title_case(name: &str) -> String {
    let mut out = String::new();
    let mut upper = true;
    let mut prev_lower_or_digit = false;
    for ch in name.chars() {
        if ch == '_' || ch == '-' {
            out.push(' ');
            upper = true;
            prev_lower_or_digit = false;
        } else if ch.is_uppercase() && prev_lower_or_digit {
            out.push(' ');
            out.push(ch);
            upper = false;
            prev_lower_or_digit = false;
        } else if upper {
            for c in ch.to_uppercase() {
                out.push(c);
            }
            upper = false;
            prev_lower_or_digit = ch.is_lowercase() || ch.is_ascii_digit();
        } else {
            out.push(ch);
            prev_lower_or_digit = ch.is_lowercase() || ch.is_ascii_digit();
        }
    }
    out
}

fn field_from_payload(name: &str, raw: &Value) -> Field {
    if let Some(obj) = raw.as_object() {
        if obj.contains_key("type") && obj.get("name").is_none() {
            return field_from_spec(name, raw);
        }
        let type_obj = raw.get("type").and_then(Value::as_object);
        let type_payload = type_obj
            .map(|value| Value::Object(value.clone()))
            .unwrap_or_else(|| raw.clone());
        let mut field_type = field_type_from_payload(&type_payload);
        if field_type.name.is_empty() {
            field_type.name = raw
                .get("name")
                .and_then(Value::as_str)
                .unwrap_or("string")
                .to_string();
        }
        let mut field = Field::new(name, field_type);
        field.title = raw
            .get("title")
            .and_then(Value::as_str)
            .map(ToString::to_string)
            .unwrap_or_else(|| title_case(name));
        field.description = raw
            .get("description")
            .and_then(Value::as_str)
            .map(ToString::to_string);
        field.is_optional = bool_key(raw, &["isOptional", "optional"]);
        field.is_internal = bool_key(raw, &["isInternal", "internal"]);
        field.is_cached = bool_key(raw, &["isCached", "cache", "cached"]);
        return field;
    }
    Field::new(name, FieldType::string())
}

fn field_type_from_payload(raw: &Value) -> FieldType {
    let mut field_type =
        FieldType::new(raw.get("name").and_then(Value::as_str).unwrap_or("string"));
    field_type.is_array = raw
        .get("isArray")
        .or_else(|| raw.get("array"))
        .and_then(Value::as_bool)
        .unwrap_or(false);
    field_type.options = raw.get("options").and_then(Value::as_array).map(|items| {
        items
            .iter()
            .filter_map(Value::as_str)
            .map(ToString::to_string)
            .collect()
    });
    field_type.fields = raw.get("fields").and_then(Value::as_object).cloned();
    field_type.min_length = number_key(raw, &["minLength"]);
    field_type.max_length = number_key(raw, &["maxLength"]);
    field_type.minimum = number_key(raw, &["minimum"]);
    field_type.maximum = number_key(raw, &["maximum"]);
    field_type.pattern = raw
        .get("pattern")
        .and_then(Value::as_str)
        .map(ToString::to_string);
    field_type.pattern_description = raw
        .get("patternDescription")
        .and_then(Value::as_str)
        .map(ToString::to_string);
    field_type.format = raw
        .get("format")
        .and_then(Value::as_str)
        .map(ToString::to_string);
    field_type.language = raw
        .get("language")
        .and_then(Value::as_str)
        .map(ToString::to_string);
    field_type.description = raw
        .get("description")
        .and_then(Value::as_str)
        .map(ToString::to_string);
    field_type
}

fn field_from_spec(name: &str, raw: &Value) -> Field {
    let type_name = raw.get("type").and_then(Value::as_str).unwrap_or("string");
    let mut type_payload = Map::new();
    type_payload.insert("name".to_string(), Value::String(type_name.to_string()));
    type_payload.insert(
        "isArray".to_string(),
        Value::Bool(bool_key(raw, &["array", "isArray"])),
    );
    if let Some(options) = raw.get("options") {
        type_payload.insert("options".to_string(), options.clone());
    }
    if let Some(fields) = raw.get("fields").and_then(Value::as_object) {
        let mut nested = Map::new();
        for (child_name, child_spec) in fields {
            nested.insert(
                child_name.clone(),
                field_payload_with_type_description(&field_from_spec(child_name, child_spec)),
            );
        }
        type_payload.insert("fields".to_string(), Value::Object(nested));
    }
    if let Some(value) = number_key(raw, &["minLength"]) {
        type_payload.insert("minLength".to_string(), json_number(value));
    }
    if let Some(value) = number_key(raw, &["maxLength"]) {
        type_payload.insert("maxLength".to_string(), json_number(value));
    }
    if let Some(value) = number_key(raw, &["min", "minimum"]) {
        let key = if type_name == "string" {
            "minLength"
        } else {
            "minimum"
        };
        type_payload.insert(key.to_string(), json_number(value));
    }
    if let Some(value) = number_key(raw, &["max", "maximum"]) {
        let key = if type_name == "string" {
            "maxLength"
        } else {
            "maximum"
        };
        type_payload.insert(key.to_string(), json_number(value));
    }
    if let Some(value) = raw.get("pattern").and_then(Value::as_str) {
        type_payload.insert("pattern".to_string(), Value::String(value.to_string()));
    }
    if let Some(value) = raw.get("patternDescription").and_then(Value::as_str) {
        type_payload.insert(
            "patternDescription".to_string(),
            Value::String(value.to_string()),
        );
    }
    if bool_key(raw, &["email"]) {
        type_payload.insert("format".to_string(), Value::String("email".to_string()));
    } else if bool_key(raw, &["url"]) {
        type_payload.insert("format".to_string(), Value::String("uri".to_string()));
    } else if let Some(value) = raw.get("format").and_then(Value::as_str) {
        type_payload.insert("format".to_string(), Value::String(value.to_string()));
    }
    if let Some(description) = raw.get("description").and_then(Value::as_str) {
        if type_name != "object" || bool_key(raw, &["array", "isArray"]) {
            type_payload.insert(
                "description".to_string(),
                Value::String(description.to_string()),
            );
        }
    }
    let mut field = Field::new(name, field_type_from_payload(&Value::Object(type_payload)));
    field.title = raw
        .get("title")
        .and_then(Value::as_str)
        .map(ToString::to_string)
        .unwrap_or_else(|| title_case(name));
    field.description = raw
        .get("arrayDescription")
        .or_else(|| raw.get("description"))
        .and_then(Value::as_str)
        .map(ToString::to_string);
    field.is_optional = bool_key(raw, &["optional", "isOptional"]);
    field.is_internal = bool_key(raw, &["internal", "isInternal"]);
    field.is_cached = bool_key(raw, &["cache", "cached", "isCached"]);
    field
}

fn field_payload_with_type_description(field: &Field) -> Value {
    field_payload_impl(field, true)
}

fn field_payload(field: &Field) -> Value {
    field_payload_impl(field, false)
}

fn field_payload_impl(field: &Field, include_type_description: bool) -> Value {
    let mut out = Map::new();
    out.insert("name".to_string(), Value::String(field.name.clone()));
    out.insert("title".to_string(), Value::String(field.title.clone()));
    out.insert(
        "type".to_string(),
        if include_type_description {
            field.field_type.to_payload_with_description()
        } else {
            field.field_type.to_payload()
        },
    );
    out.insert("isOptional".to_string(), Value::Bool(field.is_optional));
    out.insert("isInternal".to_string(), Value::Bool(field.is_internal));
    out.insert("isCached".to_string(), Value::Bool(field.is_cached));
    if let Some(description) = &field.description {
        out.insert(
            "description".to_string(),
            Value::String(description.clone()),
        );
    }
    Value::Object(out)
}

fn signature_payload(sig: &AxSignature) -> Value {
    json!({
        "description": sig.description,
        "inputs": sig.inputs.iter().map(field_payload_with_type_description).collect::<Vec<_>>(),
        "outputs": sig.outputs.iter().map(field_payload_with_type_description).collect::<Vec<_>>()
    })
}

pub fn signature_from_spec(spec: &Value) -> AxResult<AxSignature> {
    let mut inputs = Vec::new();
    let mut outputs = Vec::new();
    if let Some(raw_inputs) = spec.get("inputs").and_then(Value::as_object) {
        for (name, raw) in raw_inputs {
            inputs.push(field_from_spec(name, raw));
        }
    }
    if let Some(raw_outputs) = spec.get("outputs").and_then(Value::as_object) {
        for (name, raw) in raw_outputs {
            outputs.push(field_from_spec(name, raw));
        }
    }
    let values = core_value_from_json(&json!({
        "inputs": inputs.iter().map(field_payload).collect::<Vec<_>>(),
        "outputs": outputs.iter().map(field_payload).collect::<Vec<_>>(),
    }));
    let record = core_record_new(&[CoreValue::from("AxSignature"), values])?;
    validate_signature(&[record])?;
    Ok(AxSignature {
        description: spec
            .get("description")
            .and_then(Value::as_str)
            .map(ToString::to_string),
        inputs,
        outputs,
    })
}

fn build_fixture_signature(fixture: &Value) -> AxResult<AxSignature> {
    if let Some(spec) = fixture.get("signature_spec") {
        return signature_from_spec(spec);
    }
    if let Some(spec) = fixture.get("signature").and_then(Value::as_object) {
        return signature_from_spec(&Value::Object(spec.clone()));
    }
    s(fixture
        .get("signature")
        .and_then(Value::as_str)
        .unwrap_or("question:string -> answer:string"))
}

fn trim_num(value: f64) -> String {
    if value.fract() == 0.0 {
        format!("{}", value as i64)
    } else {
        value.to_string()
    }
}

// Decode a standard-alphabet base64 string into raw bytes. Mirrors Python's
// base64.b64decode tolerance: whitespace is ignored and the input may omit
// trailing padding. Invalid characters terminate decoding (the caller falls
// back to the raw UTF-8 bytes when this yields nothing usable).
fn decode_base64(input: &str) -> Vec<u8> {
    fn sextet(byte: u8) -> Option<u8> {
        match byte {
            b'A'..=b'Z' => Some(byte - b'A'),
            b'a'..=b'z' => Some(byte - b'a' + 26),
            b'0'..=b'9' => Some(byte - b'0' + 52),
            b'+' => Some(62),
            b'/' => Some(63),
            _ => None,
        }
    }
    let mut out = Vec::new();
    let mut buffer: u32 = 0;
    let mut bits = 0u32;
    for &byte in input.as_bytes() {
        if byte == b'=' {
            break;
        }
        if byte.is_ascii_whitespace() {
            continue;
        }
        let value = match sextet(byte) {
            Some(value) => value,
            None => break,
        };
        buffer = (buffer << 6) | u32::from(value);
        bits += 6;
        if bits >= 8 {
            bits -= 8;
            out.push((buffer >> bits) as u8);
        }
    }
    out
}

// Encode raw bytes as a standard-alphabet base64 string (with `=` padding).
// Inverse of `decode_base64`; used for binary responses (e.g. OpenAI
// /audio/speech returns raw mp3) which must not be UTF-8 decoded. Mirrors the
// verified Python `base64.b64encode(...).decode()`.
fn encode_base64(input: &[u8]) -> String {
    const ALPHABET: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut out = String::with_capacity((input.len() + 2) / 3 * 4);
    for chunk in input.chunks(3) {
        let b0 = chunk[0] as u32;
        let b1 = chunk.get(1).copied().unwrap_or(0) as u32;
        let b2 = chunk.get(2).copied().unwrap_or(0) as u32;
        let triple = (b0 << 16) | (b1 << 8) | b2;
        out.push(ALPHABET[((triple >> 18) & 0x3f) as usize] as char);
        out.push(ALPHABET[((triple >> 12) & 0x3f) as usize] as char);
        if chunk.len() > 1 {
            out.push(ALPHABET[((triple >> 6) & 0x3f) as usize] as char);
        } else {
            out.push('=');
        }
        if chunk.len() > 2 {
            out.push(ALPHABET[(triple & 0x3f) as usize] as char);
        } else {
            out.push('=');
        }
    }
    out
}

// Encode a request payload as multipart/form-data and return the raw body
// bytes plus the matching Content-Type header value. Multipart operations
// (e.g. OpenAI /audio/transcriptions) carry the audio as a binary `file` part;
// every other field is a plain form field. The `file` value is a base64 string
// (optionally a `data:` URL) or a map {data, mimeType?, filename?}. Mirrors the
// verified Python `_encode_multipart`; the fixed boundary avoids needing a
// random/uuid dependency.
fn encode_multipart(payload: &Value) -> (Vec<u8>, String) {
    const BOUNDARY: &str = "----axllmFormBoundaryAx7LlmMultipartBoundary";
    const CRLF: &[u8] = b"\r\n";
    let mut body: Vec<u8> = Vec::new();
    if let Some(entries) = payload.as_object() {
        for (key, value) in entries {
            if value.is_null() {
                continue;
            }
            if key == "file" {
                let (raw_data, filename, content_type) = match value {
                    Value::Object(map) => {
                        let data = map
                            .get("data")
                            .and_then(Value::as_str)
                            .unwrap_or("")
                            .to_string();
                        let filename = map
                            .get("filename")
                            .and_then(Value::as_str)
                            .filter(|name| !name.is_empty())
                            .unwrap_or("audio.wav")
                            .to_string();
                        let content_type = map
                            .get("mimeType")
                            .or_else(|| map.get("mime_type"))
                            .and_then(Value::as_str)
                            .filter(|mime| !mime.is_empty())
                            .unwrap_or("audio/wav")
                            .to_string();
                        (data, filename, content_type)
                    }
                    _ => (
                        value_as_display_string(value),
                        "audio.wav".to_string(),
                        "audio/wav".to_string(),
                    ),
                };
                let stripped = if raw_data.starts_with("data:") {
                    match raw_data.split_once(',') {
                        Some((_, rest)) => rest.to_string(),
                        None => raw_data.clone(),
                    }
                } else {
                    raw_data.clone()
                };
                let mut file_bytes = decode_base64(&stripped);
                if file_bytes.is_empty() && !stripped.is_empty() {
                    file_bytes = stripped.into_bytes();
                }
                body.extend_from_slice(b"--");
                body.extend_from_slice(BOUNDARY.as_bytes());
                body.extend_from_slice(CRLF);
                body.extend_from_slice(
                    format!(
                        "Content-Disposition: form-data; name=\"file\"; filename=\"{filename}\""
                    )
                    .as_bytes(),
                );
                body.extend_from_slice(CRLF);
                body.extend_from_slice(format!("Content-Type: {content_type}").as_bytes());
                body.extend_from_slice(CRLF);
                body.extend_from_slice(CRLF);
                body.extend_from_slice(&file_bytes);
                body.extend_from_slice(CRLF);
            } else {
                body.extend_from_slice(b"--");
                body.extend_from_slice(BOUNDARY.as_bytes());
                body.extend_from_slice(CRLF);
                body.extend_from_slice(
                    format!("Content-Disposition: form-data; name=\"{key}\"").as_bytes(),
                );
                body.extend_from_slice(CRLF);
                body.extend_from_slice(CRLF);
                body.extend_from_slice(value_as_display_string(value).as_bytes());
                body.extend_from_slice(CRLF);
            }
        }
    }
    body.extend_from_slice(b"--");
    body.extend_from_slice(BOUNDARY.as_bytes());
    body.extend_from_slice(b"--");
    body.extend_from_slice(CRLF);
    (body, format!("multipart/form-data; boundary={BOUNDARY}"))
}

fn json_number(value: f64) -> Value {
    if value.fract() == 0.0 {
        json!(value as i64)
    } else {
        json!(value)
    }
}

fn number_key(value: &Value, keys: &[&str]) -> Option<f64> {
    keys.iter()
        .find_map(|key| value.get(*key).and_then(Value::as_f64))
}

fn bool_key(value: &Value, keys: &[&str]) -> bool {
    keys.iter()
        .any(|key| value.get(*key).and_then(Value::as_bool).unwrap_or(false))
}

pub trait AxAIClient {
    fn chat(&mut self, request: Value) -> AxResult<Value>;

    fn chat_with_options(&mut self, request: Value, _options: Value) -> AxResult<Value> {
        self.chat(request)
    }

    fn chat_with_runtime_hooks(
        &mut self,
        request: Value,
        options: Value,
        hooks: AxRuntimeHooks,
    ) -> AxResult<Value> {
        with_runtime_scope(
            Some(&hooks),
            None,
            "ax_llm_chat",
            "client",
            BTreeMap::new(),
            || self.chat_with_options(request, options),
        )
    }

    fn embed(&mut self, _request: Value) -> AxResult<Value> {
        Err(AxError::runtime(
            "embedding is not supported by this AI client",
        ))
    }

    fn embed_with_runtime_hooks(
        &mut self,
        request: Value,
        hooks: AxRuntimeHooks,
    ) -> AxResult<Value> {
        with_runtime_scope(
            Some(&hooks),
            None,
            "ax_llm_embed",
            "client",
            BTreeMap::new(),
            || self.embed(request),
        )
    }

    fn speak(&mut self, _request: Value) -> AxResult<Value> {
        Err(AxError::runtime(
            "speech is not supported by this AI client",
        ))
    }

    fn get_id(&self) -> String {
        self.get_name()
    }
    fn get_name(&self) -> String {
        "ai-service".to_string()
    }
    fn get_features(&self, _model: Option<&str>) -> Value {
        router_default_features()
    }
    fn get_model_list(&self) -> Value {
        Value::Null
    }
    fn get_metrics(&self) -> Value {
        json!({"latency":{"chat":{"mean":0,"p95":0,"p99":0,"samples":[]},"embed":{"mean":0,"p95":0,"p99":0,"samples":[]}},"errors":{"chat":{"count":0,"rate":0,"total":0},"embed":{"count":0,"rate":0,"total":0}}})
    }
    fn get_estimated_cost(&self, _usage: &Value) -> f64 {
        0.0
    }
    fn get_options(&self) -> Value {
        json!({})
    }
    fn set_options(&mut self, _options: Value) {}

    fn transcribe(&mut self, request: Value) -> AxResult<Value> {
        let _ = request;
        Ok(json!({"text": ""}))
    }

    fn complete(&mut self, request: Value) -> AxResult<Value> {
        self.chat(request)
    }

    fn stream(&mut self, request: Value) -> AxResult<Vec<Value>> {
        let response = self.chat(request)?;
        if let Some(results) = response.get("results").and_then(Value::as_array) {
            return Ok(results
                .iter()
                .map(|result| json!({"results": [result.clone()]}))
                .collect());
        }
        Ok(vec![response])
    }

    fn stream_iter(&mut self, request: Value) -> AxResult<AxChatStream> {
        self.stream(request).map(AxChatStream::from_values)
    }

    fn stream_with_runtime_hooks(
        &mut self,
        request: Value,
        hooks: AxRuntimeHooks,
    ) -> AxResult<Vec<Value>> {
        with_runtime_scope(
            Some(&hooks),
            None,
            "ax_llm_chat",
            "client",
            BTreeMap::new(),
            || self.stream(request),
        )
    }
}

pub type AIClient = dyn AxAIClient;

type AxStreamFinish = Box<dyn FnOnce(&[Value], Option<&AxError>, bool)>;

pub struct AxChatStream {
    inner: Box<dyn Iterator<Item = AxResult<Value>>>,
    values: Vec<Value>,
    finish: Option<AxStreamFinish>,
    finished: bool,
}

impl AxChatStream {
    fn new(
        inner: impl Iterator<Item = AxResult<Value>> + 'static,
        finish: Option<AxStreamFinish>,
    ) -> Self {
        Self {
            inner: Box::new(inner),
            values: Vec::new(),
            finish,
            finished: false,
        }
    }

    fn from_values(values: Vec<Value>) -> Self {
        Self::new(values.into_iter().map(Ok), None)
    }

    fn complete(&mut self, error: Option<&AxError>, cancelled: bool) {
        if self.finished {
            return;
        }
        self.finished = true;
        if let Some(finish) = self.finish.take() {
            finish(&self.values, error, cancelled);
        }
    }
}

impl Iterator for AxChatStream {
    type Item = AxResult<Value>;

    fn next(&mut self) -> Option<Self::Item> {
        if self.finished {
            return None;
        }
        match self.inner.next() {
            Some(Ok(value)) => {
                self.values.push(value.clone());
                Some(Ok(value))
            }
            Some(Err(error)) => {
                self.inner = Box::new(std::iter::empty());
                self.complete(Some(&error), false);
                Some(Err(error))
            }
            None => {
                self.inner = Box::new(std::iter::empty());
                self.complete(None, false);
                None
            }
        }
    }
}

impl Drop for AxChatStream {
    fn drop(&mut self) {
        if !self.finished {
            let error = AxError {
                category: "response".into(),
                error_type: Some("AxAIServiceStreamTerminatedError".into()),
                message: "stream cancelled".into(),
                status: None,
                code: None,
                retryable: true,
                response_body: None,
            };
            self.complete(Some(&error), true);
        }
    }
}

pub enum AxTransportStream {
    Buffered(Value),
    Reader { status: u16, body: Box<dyn Read> },
}

pub trait AxTransport: Send {
    fn send(&mut self, request: Value) -> AxResult<Value>;

    fn stream(&mut self, request: Value) -> AxResult<AxTransportStream> {
        self.send(request).map(AxTransportStream::Buffered)
    }
}

struct SseJsonStream {
    reader: BufReader<Box<dyn Read>>,
    line: Vec<u8>,
    data_lines: Vec<String>,
    skip_lf: bool,
    at_start: bool,
    done: bool,
}

impl SseJsonStream {
    fn new(reader: Box<dyn Read>) -> Self {
        Self {
            reader: BufReader::new(reader),
            line: Vec::new(),
            data_lines: Vec::new(),
            skip_lf: false,
            at_start: true,
            done: false,
        }
    }

    fn flush_event(&mut self) -> AxResult<Option<Value>> {
        if self.data_lines.is_empty() {
            return Ok(None);
        }
        let payload = self.data_lines.join("\n");
        self.data_lines.clear();
        if payload.trim() == "[DONE]" {
            self.done = true;
            return Ok(None);
        }
        serde_json::from_str(&payload)
            .map(Some)
            .map_err(AxError::from)
    }

    fn process_line(&mut self) -> AxResult<Option<Value>> {
        let bytes = std::mem::take(&mut self.line);
        let mut line = String::from_utf8(bytes).map_err(|error| {
            AxError::new("response", format!("invalid UTF-8 in SSE stream: {error}"))
        })?;
        if self.at_start {
            self.at_start = false;
            line = line.strip_prefix('\u{feff}').unwrap_or(&line).to_string();
        }
        if line.is_empty() {
            return self.flush_event();
        }
        if line.starts_with(':') {
            return Ok(None);
        }
        let (field, mut value) = match line.find(':') {
            Some(index) => (&line[..index], &line[index + 1..]),
            None => (line.as_str(), ""),
        };
        if let Some(stripped) = value.strip_prefix(' ') {
            value = stripped;
        }
        if field == "data" {
            self.data_lines.push(value.to_string());
        }
        Ok(None)
    }
}

impl Iterator for SseJsonStream {
    type Item = AxResult<Value>;

    fn next(&mut self) -> Option<Self::Item> {
        if self.done {
            return None;
        }
        loop {
            let mut byte = [0u8; 1];
            match self.reader.read(&mut byte) {
                Ok(0) => {
                    let line_result = if self.line.is_empty() {
                        Ok(None)
                    } else {
                        self.process_line()
                    };
                    match line_result {
                        Err(error) => {
                            self.done = true;
                            return Some(Err(error));
                        }
                        Ok(Some(event)) => {
                            self.done = true;
                            return Some(Ok(event));
                        }
                        Ok(None) => {}
                    }
                    self.done = true;
                    return match self.flush_event() {
                        Ok(Some(event)) => Some(Ok(event)),
                        Ok(None) => None,
                        Err(error) => Some(Err(error)),
                    };
                }
                Err(error) => {
                    self.done = true;
                    return Some(Err(AxError {
                        category: "response".into(),
                        error_type: Some("AxAIServiceStreamTerminatedError".into()),
                        message: error.to_string(),
                        status: None,
                        code: None,
                        retryable: true,
                        response_body: None,
                    }));
                }
                Ok(_) => {}
            }
            let value = byte[0];
            if self.skip_lf {
                self.skip_lf = false;
                if value == b'\n' {
                    continue;
                }
            }
            if value == b'\r' || value == b'\n' {
                if value == b'\r' {
                    self.skip_lf = true;
                }
                match self.process_line() {
                    Ok(Some(event)) => return Some(Ok(event)),
                    Ok(None) if self.done => return None,
                    Ok(None) => continue,
                    Err(error) => {
                        self.done = true;
                        return Some(Err(error));
                    }
                }
            }
            self.line.push(value);
        }
    }
}

struct NormalizedProviderStream {
    raw: Box<dyn Iterator<Item = AxResult<Value>>>,
    first: Option<Value>,
    profile: String,
    model: String,
    state: CoreValue,
}

impl Iterator for NormalizedProviderStream {
    type Item = AxResult<Value>;

    fn next(&mut self) -> Option<Self::Item> {
        loop {
            let raw = match self.first.take() {
                Some(value) => Ok(value),
                None => self.raw.next()?,
            };
            let event = match raw {
                Ok(value) => value,
                Err(error) => return Some(Err(error)),
            };
            let normalized = provider_normalize_stream_delta(&[
                CoreValue::from(self.profile.as_str()),
                core_value_from_json(&event),
                self.state.clone(),
                provider_ai_display_name(&self.profile),
                CoreValue::from(self.model.as_str()),
            ]);
            match normalized {
                Ok(value) if value.is_null() => continue,
                Ok(value) => return Some(Ok(core_value_to_json(&value))),
                Err(error) => return Some(Err(error)),
            }
        }
    }
}

#[derive(Clone, Debug)]
pub struct AxCredentialRequest {
    pub profile: String,
    pub operation: String,
    pub method: String,
    pub url: String,
}

pub trait AxCredentialProvider: Send + Sync {
    fn credentials(&self, request: &AxCredentialRequest) -> AxResult<BTreeMap<String, String>>;
}

impl<F> AxCredentialProvider for F
where
    F: Fn(&AxCredentialRequest) -> AxResult<BTreeMap<String, String>> + Send + Sync,
{
    fn credentials(&self, request: &AxCredentialRequest) -> AxResult<BTreeMap<String, String>> {
        self(request)
    }
}

// Hosts can provide a tenant-aware registry; keys remain the stable
// provider:model:contentHash tuple used by the in-process registry.
pub trait AxContextCacheRegistry: Send {
    fn get(&mut self, namespace: &str, key: &str) -> Option<Value>;
    fn set(&mut self, namespace: &str, key: &str, entry: Value);
}

pub type RuntimeTransport = dyn AxTransport;

pub struct ScriptedTransport {
    responses: VecDeque<Value>,
    pub requests: Vec<Value>,
}

impl ScriptedTransport {
    pub fn new(responses: Vec<Value>) -> Self {
        Self {
            responses: responses.into(),
            requests: Vec::new(),
        }
    }
}

impl AxTransport for ScriptedTransport {
    fn send(&mut self, request: Value) -> AxResult<Value> {
        self.requests.push(request);
        self.responses
            .pop_front()
            .ok_or_else(|| AxError::runtime("scripted transport exhausted"))
    }
}

