        v_field_title = core_get(&v_field, &CoreValue::from("title"), CoreValue::Null);
        v_is_optional = core_get(
            &v_field,
            &CoreValue::from("is_optional"),
            CoreValue::Bool(false),
        );
        v_has_value = core_map_contains(&[v_values.clone(), v_field_name.clone()])?;
