    let mut v_input_cost = CoreValue::Null;
    let mut v_is_google_name = CoreValue::Null;
    let mut v_is_openai_compatible = CoreValue::Null;
    let mut v_long_context = CoreValue::Null;
    let mut v_matches = CoreValue::Null;
