    let mut v_opts = CoreValue::Null;
    let mut v_opts_missing = CoreValue::Null;
    let mut v_read_error = CoreValue::Null;
    let mut v_read_error_snake = CoreValue::Null;
    let mut v_result = CoreValue::Null;
